//! Regression coverage for chunked kitty graphics transmission as monstar
//! consumes it: the App feeds PTY batches through `vt.Stream`, so inline
//! `o=z` payloads must survive single-chunk, true multi-chunk (m=1..m=0),
//! and arbitrarily split feeds before reaching the terminal storage.

const std = @import("std");
const vt = @import("ghostty-vt");

const single_chunk_seq = "\x1b_Ga=T,f=32,o=z,s=120,v=60,t=d,i=99,p=1,C=1,q=2,m=0;eAHt0jERAAAMhLD3b5ra6JABA1zaSh4wwAADDDDAAAMMMMAAAwwwwAADDDDAAAMMMMAAAwwwwAADDDDAAAMMMMAAAwwwwAADDDDAAAMMMMAAAwwwwAADDDDAAAMMMMAAAwwwwAADDDDAAAMMMMAAAwwwwAADDDDAAAMMMMAAAwwwwAADDDDAAAMMMMAAAwwwwAADDDDAAAMMMMAAAwww8NrAARxnCwk=\x1b\\";

const multi_chunk_seq = "\x1b_Ga=T,f=32,o=z,s=120,v=60,t=d,i=100,p=1,C=1,q=2,m=1;\x1b\\\x1b_Gm=1;\x1b\\\x1b_Gm=1;\x1b\\\x1b_Gm=0;\x1b\\";

fn feedAndCheckImageId(
    alloc: std.mem.Allocator,
    seq: []const u8,
    image_id: u32,
    expect_len: usize,
) !void {
    var t: vt.Terminal = try .init(std.testing.io, alloc, .{ .cols = 80, .rows = 24 });
    defer t.deinit(alloc);
    var s = t.vtStream();
    defer s.deinit();

    s.nextSlice(seq);

    const img = t.screens.active.kitty_images.imageById(image_id);
    try std.testing.expect(img != null);
    if (img) |im| {
        try std.testing.expectEqual(@as(u32, 120), im.width);
        try std.testing.expectEqual(@as(u32, 60), im.height);
        try std.testing.expectEqual(expect_len, im.data.bytes().?.len);
    }
}

test "kitty graphics: single-chunk inline o=z transmit" {
    const seq = "\x1b[?2026h\x1b[H" ++ single_chunk_seq ++ "\x1b[?2026l";
    try feedAndCheckImageId(std.testing.allocator, seq, 99, 28800);
}

test "kitty graphics: multi-chunk inline o=z reassembly (m=1..m=0)" {
    const seq = "\x1b[?2026h\x1b[H" ++ multi_chunk_seq ++ "\x1b[?2026l";
    try feedAndCheckImageId(std.testing.allocator, seq, 100, 28800);
}

test "kitty graphics: multi-chunk payload split across PTY batches" {
    const alloc = std.testing.allocator;
    var t: vt.Terminal = try .init(std.testing.io, alloc, .{ .cols = 80, .rows = 24 });
    defer t.deinit(alloc);
    var s = t.vtStream();
    defer s.deinit();

    const seq = "\x1b[?2026h\x1b[H" ++ multi_chunk_seq ++ "\x1b[?2026l";
    // Feed in odd-size chunks like the read pipeline does.
    var off: usize = 0;
    var n: usize = 7;
    while (off < seq.len) {
        const end = @min(off + n, seq.len);
        s.nextSlice(seq[off..end]);
        off = end;
        n = (n * 3) % 251 + 1;
    }

    const img = t.screens.active.kitty_images.imageById(100);
    try std.testing.expect(img != null);
    if (img) |im| try std.testing.expectEqual(@as(usize, 28800), im.data.bytes().?.len);
}
